
package com.chatq.keyboardtests;
import android.content.*;import java.lang.reflect.*;import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Runs production Keystore, job manager and HTTP parser against synthetic loopback only. */
final class PersonalAiChecks {
 static int count;static void ok(boolean b,String why){if(!b)throw new AssertionError(why);count++;}
 static JSONObject await(Method read,Object jobs,String id,String state)throws Exception{JSONObject last=null;for(int i=0;i<250;i++){last=new JSONObject((String)read.invoke(jobs,id));if(last.getString("status").equals(state))return last;if(last.getString("status").equals("error")&&!state.equals("error"))throw new AssertionError(last.toString());Thread.sleep(20);}throw new AssertionError("Expected "+state+": "+last);}
 static String event(String text,String finish)throws Exception{return "data: "+new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("delta",new JSONObject().put("content",text)).put("finish_reason",finish==null?JSONObject.NULL:finish))).toString()+"\r\n\r\n";}
 static class Fixture implements AutoCloseable {
  final ServerSocket server=new ServerSocket(0);volatile String mode="json";volatile String head="";volatile JSONObject body;volatile int calls;volatile Throwable error;volatile CountDownLatch arrived=new CountDownLatch(1),closed=new CountDownLatch(1);
  Fixture()throws Exception {Thread worker=new Thread(new Runnable(){public void run(){while(!server.isClosed())try{final Socket c=server.accept();Thread t=new Thread(new Runnable(){public void run(){serve(c);}});t.setDaemon(true);t.start();}catch(Exception e){if(!server.isClosed())error=e;}}});worker.setDaemon(true);worker.start();}
  void serve(Socket socket){try(Socket c=socket){c.setSoTimeout(6000);InputStream in=c.getInputStream();ByteArrayOutputStream h=new ByteArrayOutputStream();int b;while((b=in.read())!=-1){h.write(b);if(h.toString("UTF-8").endsWith("\r\n\r\n"))break;}head=h.toString("UTF-8");int length=0;for(String line:head.split("\r\n"))if(line.toLowerCase(Locale.ROOT).startsWith("content-length:"))length=Integer.parseInt(line.substring(15).trim());byte[] raw=new byte[length];int offset=0,n;while(offset<length&&(n=in.read(raw,offset,length-offset))>0)offset+=n;body=new JSONObject(new String(raw,"UTF-8"));calls++;String m=mode;OutputStream out=c.getOutputStream();
   if(m.equals("auth")||m.equals("redirect")){String code=m.equals("auth")?"401 Unauthorized":"302 Found";out.write(("HTTP/1.1 "+code+"\r\nLocation: http://localhost:"+server.getLocalPort()+"/stolen\r\nContent-Length: 25\r\nConnection: close\r\n\r\nfixture-secret-not-echoed!").getBytes("UTF-8"));out.flush();arrived.countDown();return;}
   if(m.equals("json")){String content=body.optBoolean("stream")?"错误测试":"{\"candidates\":[\"自然回复\",\"自然回复\",\"另一条\"]}";byte[] value=new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("message",new JSONObject().put("content",content)).put("finish_reason","stop"))).toString().getBytes("UTF-8");out.write(("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: "+value.length+"\r\nConnection: close\r\n\r\n").getBytes("UTF-8"));out.write(value);out.flush();arrived.countDown();return;}
   out.write("HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nConnection: close\r\n\r\n".getBytes("UTF-8"));for(byte x:event("你好🙂",null).getBytes("UTF-8")){out.write(x);out.flush();}arrived.countDown();
   if(m.equals("cut"))return;
   if(m.equals("wait")){try{while(in.read()!=-1){}}finally{closed.countDown();}return;}
   out.write(event("",m.equals("length")?"length":"stop").getBytes("UTF-8"));out.write("data: [DONE]\r\n\r\n".getBytes("UTF-8"));out.flush();
  }catch(Exception e){if(!mode.equals("wait"))error=e;}}
  void mode(String value){mode=value;arrived=new CountDownLatch(1);closed=new CountDownLatch(1);error=null;}
  public void close()throws Exception{server.close();}
 }
 static int run(Context actual)throws Exception{
  // Separate preference namespace; never overwrite a real user's provider configuration.
  Context context=new ContextWrapper(actual){public SharedPreferences getSharedPreferences(String name,int mode){return super.getSharedPreferences("free125_test_"+name,mode);}};
  SharedPreferences prefs=context.getSharedPreferences("chatq_personal_ai_v1",0),personal=context.getSharedPreferences("chatq_keyboard",0);prefs.edit().clear().commit();personal.edit().clear().commit();
  ClassLoader loader=actual.getClassLoader();Class<?> vaultType=loader.loadClass("expo.modules.chatqkeyboard.PersonalAiVault"),jobType=loader.loadClass("expo.modules.chatqkeyboard.PersonalAiJobs");Object vault=vaultType.getConstructor(Context.class).newInstance(context),jobs=jobType.getConstructor(Context.class).newInstance(context);
  Method save=vaultType.getMethod("save",String.class),load=vaultType.getMethod("load"),meta=vaultType.getMethod("metadata"),clear=vaultType.getMethod("clear"),start=jobType.getMethod("start",String.class,String.class,String.class),read=jobType.getMethod("read",String.class),cancel=jobType.getMethod("cancel",String.class),release=jobType.getMethod("release",String.class);
  try(Fixture f=new Fixture()){
   ok(load.invoke(vault)==null,"no implicit default API or credential");
   JSONObject config=new JSONObject().put("baseUrl","http://127.0.0.1:"+f.server.getLocalPort()+"/custom/v1/").put("apiKey","fixture-secret-not-echoed").put("model","fixture-model").put("stream",true);
   save.invoke(vault,config.toString());String metadata=(String)meta.invoke(vault);ok(!metadata.contains("fixture-secret")&&!metadata.contains("apiKey"),"bridge metadata does not expose secret");ok(!prefs.getAll().toString().contains("fixture-secret"),"preferences contain only encrypted API config");
   Object reopened=vaultType.getConstructor(Context.class).newInstance(context);ok(((JSONObject)load.invoke(reopened)).getString("apiKey").equals("fixture-secret-not-echoed"),"Keystore roundtrip across instances");
   config.put("apiKey","");save.invoke(vault,config.toString());ok(((JSONObject)load.invoke(vault)).getString("apiKey").equals("fixture-secret-not-echoed"),"blank unchanged endpoint retains key");
   for(String base:new String[]{"https://different.invalid/v1","http://example.test/v1","https://u:p@example.test/v1","https://example.test/v1?key=x"}){JSONObject bad=new JSONObject(config.toString()).put("baseUrl",base);try{save.invoke(vault,bad.toString());throw new AssertionError("unsafe endpoint accepted");}catch(InvocationTargetException e){ok(e.getCause() instanceof IllegalArgumentException,"changed endpoint cannot reuse secret");}}
   for(String base:new String[]{"http://example.test/v1","https://u:p@example.test/v1","https://example.test/v1?key=x","https://example.test/v1/chat/completions"}){try{save.invoke(vault,new JSONObject(config.toString()).put("baseUrl",base).put("apiKey","fixture").toString());throw new AssertionError("unsafe root accepted");}catch(InvocationTargetException e){ok(e.getCause() instanceof IllegalArgumentException,"unsafe root rejected before network");}}
   personal.edit().putString("personalization",new JSONObject().put("relations",new JSONArray().put(new JSONObject().put("id","friend").put("name","朋友"))).put("tagNames",new JSONObject().put("gentle","温柔")).toString()).commit();
   JSONObject request=new JSONObject().put("prompt","合成问题").put("candidateCount",3).put("customPrompt","不要说教").put("relationId","friend").put("personaTagWeights",new JSONObject().put("gentle",0.6));
   String id="personal_native_reply_1";start.invoke(jobs,id,"reply",request.toString());JSONObject result=await(read,jobs,id,"done");ok(new JSONObject(result.getString("result")).getJSONArray("candidates").length()==2,"candidate duplicates removed");
   ok(f.head.startsWith("POST /custom/v1/chat/completions "),"provider base path retained");String lower=f.head.toLowerCase(Locale.ROOT);ok(lower.contains("authorization: bearer fixture-secret-not-echoed")&&!lower.contains("x-api-key:")&&!lower.contains("x-device-id:"),"only personal provider credential transmitted");
   String system=f.body.getJSONArray("messages").getJSONObject(0).getString("content");ok(system.contains("不要说教")&&system.contains("朋友")&&system.contains("温柔"),"persona instructions and human-readable choices in prompt");release.invoke(jobs,id);
   for(String mode:new String[]{"stream","cut","length","auth","redirect"}){f.mode(mode);id="personal_native_"+mode;start.invoke(jobs,id,"chat",new JSONObject().put("prompt","继续").put("history",new JSONArray().put(new JSONObject().put("role","user").put("content","前一问"))).toString());result=await(read,jobs,id,mode.equals("stream")?"done":"error");if(mode.equals("stream")){ok(new JSONObject(result.getString("result")).getString("reply").equals("你好🙂"),"split UTF-8 SSE with finish and DONE completes");ok(f.body.getJSONArray("messages").length()==3,"prior turn and current question sent");}else{ok(result.getString("result").isEmpty(),"failed or truncated stream never completes");ok(!result.getString("error").contains("fixture-secret"),"provider error cannot reflect key");}release.invoke(jobs,id);if(f.error!=null)throw new AssertionError(f.error);}
   ok(f.calls==6,"no redirect follow or implicit retry");
   f.mode("wait");id="personal_native_cancel";start.invoke(jobs,id,"chat",request.toString());ok(f.arrived.await(5,TimeUnit.SECONDS),"cancel test started");cancel.invoke(jobs,id);ok(new JSONObject((String)read.invoke(jobs,id)).getString("status").equals("cancelled"),"cancel is immediate");ok(f.closed.await(5,TimeUnit.SECONDS),"cancellation closes actual HTTP socket");release.invoke(jobs,id);
   id="personal_native_preabort";cancel.invoke(jobs,id);try{start.invoke(jobs,id,"reply",request.toString());throw new AssertionError("precancel started");}catch(InvocationTargetException e){ok(e.getCause() instanceof CancellationException,"precancel never opens socket");}ok(f.calls==7,"exactly one call per explicit request");
   prefs.edit().putString("value","corrupt").commit();try{load.invoke(vault);throw new AssertionError("corrupt config accepted");}catch(InvocationTargetException e){ok(e.getCause() instanceof IllegalStateException,"corrupt config is explicit not fallback");}
   clear.invoke(vault);ok(load.invoke(vault)==null&&!new JSONObject((String)meta.invoke(vault)).getBoolean("hasKey"),"clear removes key and readiness");
   return count;
  }finally{jobType.getMethod("destroy").invoke(jobs);prefs.edit().clear().commit();personal.edit().clear().commit();}
 }
}
